<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue';
import { useRoute } from 'vue-router';
import { useAuth } from '../composables/useAuth';
import FinanceCalendar from '../components/FinanceCalendar.vue';
import FinanceVaults from '../components/FinanceVaults.vue';
import CashTrajectory from '../components/CashTrajectory.vue';
import CalendarGlance from '../components/CalendarGlance.vue';
import FinanceIcon from '../components/FinanceIcon.vue';
import { financeRequest, useFinance } from '../finance/useFinance';
import { dateOffset, demoForecast } from '../finance/demo';
import { maybeAutoStart, startTour } from '../finance/tour';
import type { Commitment, FinanceAccount, FinanceGoal, Forecast, ImportPreview, Movement } from '../finance/types';
const route=useRoute();const {user}=useAuth();
const isDemo=computed(()=>route.path.startsWith('/demo'));
const section=computed(()=>String(route.params.section??route.meta.financeSection??'overview'));
const {data,loading,error,load,resetDemo,refreshDemo}=useFinance(()=>isDemo.value);

const money=(v:number|null|undefined,decimals=2)=>v==null?'—':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:decimals,maximumFractionDigits:decimals}).format(v/100);
const shortDate=(date:string)=>new Date(date+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'});
const link=(name:string)=>isDemo.value?'/demo/'+name:({overview:'/',activity:'/activity',accounts:'/ledger',forecast:'/forecast',plans:'/plans'}[name]??'/'+name);
const titles:Record<string,string>={calendar:'Your month, in perspective.',overview:'A little more breathing room.',activity:'Every little thing, accounted for.',accounts:'Your money. In one place.',forecast:'See what’s around the corner.',plans:'Make room for what matters.'};
const firstName=computed(()=>isDemo.value?'Alex':user.value?.name.split(' ')[0]??'you');
const upcoming=computed(()=>data.value?.commitments.filter(c=>c.next_date>=data.value!.as_of).sort((a,b)=>a.next_date.localeCompare(b.next_date))??[]);
const cash=computed(()=>data.value?.accounts.filter(a=>data.value!.settings.spending_account_ids.includes(a.id)).reduce((s,a)=>s+a.balance_cents,0)??0);
const worth=computed(()=>data.value?.accounts.reduce((s,a)=>s+a.balance_cents,0)??0);
const debt=computed(()=>data.value?.accounts.filter(a=>a.type==='credit_card').reduce((s,a)=>s+Math.abs(Math.min(a.balance_cents,0)),0)??0);
const breakdown=computed(()=>data.value?.forecast.breakdown??null);
const signedMoney=(v:number)=>`${v<0?'−':'+'} ${money(Math.abs(v))}`;
const paydayLabel=computed(()=>data.value?.forecast.next_income_date?`your next deposit on ${shortDate(data.value.forecast.next_income_date)}`:`${shortDate(data.value?.forecast.window_end??'')} (no deposit is scheduled, so we look 30 days ahead)`);
const spendSentence=computed(()=>{
 const f=data.value?.forecast;if(!f||f.safe_to_spend_cents===null)return 'Finish the items flagged below to get a reliable spending number.';
 return (f.headroom_cents??0)<0?`Your scheduled bills, savings and cushion need more than you have before ${paydayLabel.value}.`:`You can spend this much before ${paydayLabel.value} and still cover every scheduled bill, your savings and your cushion.`;
});
const spendingAccountNames=computed(()=>data.value?.accounts.filter(a=>data.value!.settings.spending_account_ids.includes(a.id)).map(a=>a.name).join(', ')||'none chosen yet');
const shortfall=computed(()=>Math.max(0,-(data.value?.forecast.headroom_cents??0)));
const search=ref(''),kindFilter=ref('all');
const movements=computed(()=>data.value?.movements.filter(m=>(kindFilter.value==='all'||m.kind===kindFilter.value)&&(m.description+' '+accountName(m.account_id)).toLowerCase().includes(search.value.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date)||b.id-a.id)??[]);
function accountName(id:number|null){return data.value?.accounts.find(a=>a.id===id)?.name??'Account'}
async function vaultSaved(message: string) { await load(); notice.value = message; }
function deleteDemoGoal(id: number) { if (!isDemo.value || !data.value) return; data.value.goals = data.value.goals.filter(goal => goal.id !== id); refreshDemo(); }
function saveDemoGoal(goal: FinanceGoal) { if (!isDemo.value || !data.value) return; const index = data.value.goals.findIndex(item => item.id === goal.id); if (index < 0) data.value.goals.push(goal); else data.value.goals[index] = goal; refreshDemo(); }
/** Overview panel view; a per-viewer convenience, so browser storage is fine and failures fall back to the chart. */
const glanceView=ref<'trajectory'|'calendar'>((()=>{try{return localStorage.getItem('overview-glance')==='calendar'?'calendar':'trajectory'}catch{return 'trajectory'}})());
watch(glanceView,view=>{try{localStorage.setItem('overview-glance',view)}catch{/* storage unavailable */}});
const notice=ref(''),busy=ref(false),dialog=ref<HTMLDialogElement|null>(null),modal=ref('');
watch(()=>route.path,()=>{notice.value='';load()}, {immediate:true});
watch(()=>[data.value,section.value] as const,([value,current])=>{if(value&&current==='overview')maybeAutoStart(isDemo.value?'demo':'personal',value.accounts.length>0)},{immediate:true});
const editing=ref<number|string|null>(null);
const form=ref({name:'',description:'',amount:'',date:dateOffset(0),kind:'expense',account_id:0,transfer_account_id:0,type:'checking',spendable:true,frequency:'monthly',balance:''});
watch(()=>form.value.type,type=>{if(!['checking','cash'].includes(type))form.value.spendable=false});
let returnFocus:HTMLElement|null=null;
async function openModal(type:string,item?:Movement|FinanceAccount|Commitment){returnFocus=document.activeElement as HTMLElement;modal.value=type;editing.value=item&&'id'in item?item.id:item&&'key'in item?item.key:null;form.value={name:item&&'name'in item?item.name:'',description:item&&'description'in item?item.description:'',amount:item&&'amount_cents'in item?String(item.amount_cents/100):'',date:item&&'date'in item?item.date:item&&'next_date'in item?item.next_date:dateOffset(0),kind:item&&'kind'in item?item.kind:'expense',account_id:item&&'account_id'in item?item.account_id??0:data.value?.accounts[0]?.id??0,transfer_account_id:item&&'transfer_account_id'in item?item.transfer_account_id??0:0,type:item&&'type'in item?item.type:'checking',spendable:item&&'spendable'in item?item.spendable:true,frequency:item&&'frequency'in item?item.frequency:'monthly',balance:item&&'balance_cents'in item?String(item.balance_cents/100):''};await nextTick();dialog.value?.showModal();}
async function openModalOnDate(type:string,date:string){await openModal(type);form.value.date=date}
function closeModal(){dialog.value?.close();modal.value='';returnFocus?.focus()}
async function save(){if(!data.value)return;busy.value=true;error.value='';try{
 const cents=Math.round(Number(form.value.amount)*100),balance=Math.round(Number(form.value.balance)*100);
 if(modal.value==='movement') {const payload={date:form.value.date,kind:form.value.kind,amount_cents:cents,account_id:Number(form.value.account_id),transfer_account_id:form.value.kind==='transfer'?Number(form.value.transfer_account_id):null,description:form.value.description,commitment_key:null};if(isDemo.value){const previous=data.value.movements.find(m=>m.id===editing.value);if(previous)applyMovement(previous,-1);const m={...payload,id:typeof editing.value==='number'?editing.value:Date.now()} as Movement;if(previous)data.value.movements=data.value.movements.filter(m=>m.id!==previous.id);data.value.movements.unshift(m);applyMovement(m,1)}else await financeRequest('/movements'+(editing.value?'/'+editing.value:''),payload,editing.value?'PUT':'POST');notice.value='Activity saved.'}
 else if(modal.value==='account') {const payload={name:form.value.name,type:form.value.type,opening_balance_cents:balance,opening_on:form.value.date,spendable:form.value.spendable&&['checking','cash'].includes(form.value.type)};if(isDemo.value){const id=Date.now();data.value.accounts.push({...payload,id,balance_cents:balance});if(payload.spendable)data.value.settings.spending_account_ids.push(id)}else await financeRequest('/accounts',payload);notice.value='Account added. Choose spending accounts in guardrails to include them in safe to spend.'}
 else if(modal.value==='reconcile') {if(isDemo.value){const a=data.value.accounts.find(a=>a.id===editing.value);if(a)a.balance_cents=balance}else await financeRequest('/accounts/'+editing.value+'/reconcile',{balance_cents:balance,date:form.value.date});notice.value='Balance reconciled.'}
 else if(modal.value==='commitment'){const payload={name:form.value.name,kind:form.value.kind,amount_cents:cents,account_id:Number(form.value.account_id),transfer_account_id:form.value.transfer_account_id?Number(form.value.transfer_account_id):null,frequency:form.value.frequency,next_date:form.value.date,end_date:null};if(isDemo.value){if(editing.value)data.value.commitments=data.value.commitments.filter(c=>c.key!==editing.value);data.value.commitments.push({...payload,key:typeof editing.value==='string'?editing.value:'demo-'+Date.now()});}else await financeRequest('/commitments'+(editing.value?'/'+encodeURIComponent(editing.value):''),payload,editing.value?'PUT':'POST');notice.value='Commitment saved.'}
 if(isDemo.value)refreshDemo();else await load();closeModal();
 }catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function applyMovement(m:Movement,direction:number){const source=data.value?.accounts.find(a=>a.id===m.account_id);if(source)source.balance_cents+=direction*(m.kind==='income'?m.amount_cents:-m.amount_cents);if(m.kind==='transfer'){const to=data.value?.accounts.find(a=>a.id===m.transfer_account_id);if(to)to.balance_cents+=direction*m.amount_cents}}
async function removeMovement(m:Movement){if(!window.confirm(`Delete “${m.description || 'this activity'}”?`))return;try{if(isDemo.value){applyMovement(m,-1);data.value!.movements=data.value!.movements.filter(row=>row.id!==m.id);refreshDemo()}else{await financeRequest('/movements/'+m.id,undefined,'DELETE');await load()}notice.value='Activity deleted.'}catch(e){error.value=(e as Error).message}}
async function removeCommitment(c:Commitment){if(!window.confirm(`Stop scheduling “${c.name}”?`))return;try{if(isDemo.value){data.value!.commitments=data.value!.commitments.filter(row=>row.key!==c.key);refreshDemo()}else{await financeRequest('/commitments/'+encodeURIComponent(c.key),undefined,'DELETE');await load()}notice.value='Commitment stopped.'}catch(e){error.value=(e as Error).message}}
const scenario=ref<Forecast|null>(null),whatAmount=ref('350'),whatDate=ref(dateOffset(7)),whatDirection=ref('expense');
async function runWhatIf(){if(!data.value)return;busy.value=true;try{const cents=Math.round(Number(whatAmount.value)*100)*(whatDirection.value==='expense'?-1:1);if(isDemo.value)scenario.value=demoForecast(data.value,cents,whatDate.value);else {const result=await financeRequest<{scenario:Forecast}>('/forecast',{events:[{date:whatDate.value,account_id:data.value.accounts.find(a=>a.spendable)?.id??data.value.accounts[0]?.id,amount_cents:cents}]});scenario.value=result.scenario}}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
const cushion=ref(''),allowance=ref(''),selectedSpendingAccounts=ref<number[]>([]);
watch(data,()=>{cushion.value=String((data.value?.settings.cushion_cents??0)/100);allowance.value=String((data.value?.settings.essential_allowance_cents??0)/100);selectedSpendingAccounts.value=[...(data.value?.settings.spending_account_ids??[])]});
async function saveSettings(){if(!data.value)return;busy.value=true;try{const settings={...data.value.settings,cushion_cents:Math.round(Number(cushion.value)*100),essential_allowance_cents:Math.round(Number(allowance.value)*100),spending_account_ids:selectedSpendingAccounts.value};if(isDemo.value){data.value.settings=settings;refreshDemo()}else {await financeRequest('/settings',settings,'PUT');await load()}notice.value='Your guardrails are updated.';closeModal()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
const csvHeaders=ref<string[]>([]),csvRows=ref<string[][]>([]),mapDate=ref(''),mapAmount=ref(''),mapDescription=ref(''),importAccount=ref(0),preview=ref<ImportPreview|null>(null),batchKey=ref('');
function parseCsv(text:string):string[][]{const rows:string[][]=[];let row:string[]=[],value='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){value+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(value);value=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(value);if(row.some(Boolean))rows.push(row);row=[];value=''}else value+=c}row.push(value);if(row.some(Boolean))rows.push(row);return rows}
async function readCsv(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;try{const rows=parseCsv(await file.text());csvHeaders.value=rows[0]??[];csvRows.value=rows.slice(1);mapDate.value=csvHeaders.value.find(h=>/date/i.test(h))??'';mapAmount.value=csvHeaders.value.find(h=>/amount/i.test(h))??'';mapDescription.value=csvHeaders.value.find(h=>/description|memo|name/i.test(h))??'';importAccount.value=data.value?.accounts[0]?.id??0;batchKey.value='csv-'+crypto.randomUUID();preview.value=null;await openModal('import')}catch(e){error.value=(e as Error).message}}
const importRows=computed(()=>csvRows.value.map(row=>{const raw=Number((row[csvHeaders.value.indexOf(mapAmount.value)]??'').replace(/[$,]/g,''));return {date:row[csvHeaders.value.indexOf(mapDate.value)]??'',kind:raw<0?'expense':'income',amount_cents:Math.round(Math.abs(raw)*100),account_id:Number(importAccount.value),description:row[csvHeaders.value.indexOf(mapDescription.value)]??''}}));
watch([mapDate,mapAmount,mapDescription,importAccount],()=>preview.value=null);
async function previewImport(){busy.value=true;try{if(isDemo.value){const rows=importRows.value.map((r,i)=>({row:i+1,valid:/^\d{4}-\d{2}-\d{2}$/.test(r.date)&&Number.isFinite(r.amount_cents)&&r.amount_cents>0,errors:[] as string[],duplicate:false}));rows.forEach(r=>{if(!r.valid)r.errors=['Use YYYY-MM-DD dates and nonzero numeric amounts.']});preview.value={rows,can_import:rows.every(r=>r.valid)}}else preview.value=await financeRequest<ImportPreview>('/imports/preview',{rows:importRows.value,batch_key:batchKey.value})}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function importCsv(){if(!preview.value?.can_import)return;busy.value=true;try{if(isDemo.value){for(const row of importRows.value){const m={...row,id:Date.now()+Math.random(),transfer_account_id:null,commitment_key:null} as Movement;data.value!.movements.push(m);applyMovement(m,1)}refreshDemo();notice.value=`Imported ${importRows.value.length} entries into the demo.`}else{const result=await financeRequest<{imported:number;skipped:number}>('/imports',{rows:importRows.value,batch_key:batchKey.value});notice.value=`Imported ${result.imported} entries. ${result.skipped} duplicates skipped.`;await load()}closeModal()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>

<template>
 <div class="finance-workspace">
  <div v-if="isDemo" class="demo-ribbon"><span><i /> Demo workspace · sample money, real possibilities</span><div><button @click="startTour('demo')">Take the tour</button><button @click="resetDemo();scenario=null;notice='Demo reset.'">Reset demo</button><RouterLink to="/login">Exit demo <span aria-hidden="true">↗</span></RouterLink></div></div>
  <header class="finance-heading"><div><p class="page-kicker">{{ section==='calendar' ? 'Your money, day by day' : section==='overview' ? 'Your money, at a glance' : section==='activity'?'The everyday ledger':section==='accounts'?'Balances & reconciliation':section==='forecast'?'The next 90 days':'Your next chapter' }}</p><h1>{{ titles[section]??titles.overview }}</h1><p>{{ section==='overview'?`Here’s where you stand, ${firstName}. Let’s give your money a direction.`:section==='calendar'?'Paydays, plans, and the space in between.':section==='forecast'?'A clear view of your commitments, before they arrive.':section==='activity'?'Log it, find it, and keep your balances honest.':section==='accounts'?'Keep an accurate starting point for every decision.':'Small commitments. Meaningful progress.' }}</p></div><button v-if="section==='overview'||section==='activity'||section==='calendar'" class="btn btn-primary" @click="openModal('movement')" :disabled="!data?.accounts.length"><FinanceIcon name="plus"/> Add activity</button><button v-else-if="section==='accounts'" class="btn btn-primary" @click="openModal('account')"><FinanceIcon name="plus"/> Add account</button><button v-else-if="section==='plans'" class="btn btn-primary" @click="openModal('commitment')" :disabled="!data?.accounts.length"><FinanceIcon name="plus"/> Add commitment</button><button v-else class="btn btn-secondary" @click="openModal('settings')">Edit guardrails</button></header>
  <p v-if="error" role="alert" class="alert">{{ error }} <button @click="load">Try again</button></p>
  <p v-if="notice" class="finance-notice" role="status"><FinanceIcon name="check"/>{{ notice }}</p>
  <div v-if="loading&&!data" class="finance-loading" role="status"><div class="loading-orbit"/> Bringing your finances into focus…</div>
  <template v-if="data">
   <section v-if="!data.accounts.length" class="onboarding"><span class="onboarding-mark"><FinanceIcon name="accounts"/></span><h2>A clear picture starts here.</h2><p>Add your current balances, then tell us what comes in and goes out. No bank password needed.</p><ol><li><strong>Add your accounts</strong><span>Use today’s cleared balances.</span></li><li><strong>Set your next income</strong><span>Your paycheck sets the planning window.</span></li><li><strong>Protect your breathing room</strong><span>Set a cushion and everyday allowance.</span></li></ol><button class="btn btn-primary" @click="openModal('account')">Add your first account <FinanceIcon name="arrow"/></button></section>
   <template v-else-if="section==='overview'">
    <div class="overview-primary">
     <section class="spend-panel"><div class="section-caption"><span class="status-dot"/> {{ data.forecast.next_income_date?'Until your next deposit · '+shortDate(data.forecast.next_income_date):'30-day fallback · through '+shortDate(data.forecast.window_end) }}<button class="icon-button" aria-label="Edit safe-to-spend guardrails" @click="openModal('settings')"><FinanceIcon name="plans"/></button></div><h2>Safe to spend</h2><div class="safe-figure">{{ money(data.forecast.safe_to_spend_cents) }}</div><p class="spend-explanation">{{ spendSentence }}</p><p v-if="shortfall && data.forecast.headroom_cents!==null" class="spend-shortfall">Projected shortfall: {{ money(shortfall) }} before the next deposit.</p><dl v-if="breakdown" class="allocation-list spend-math" aria-label="How safe to spend adds up"><div><dt>Cash in your spending accounts today</dt><dd>{{ money(breakdown.cash_cents) }}</dd></div><div><dt>{{ breakdown.scheduled_items.some(i=>i.amount_cents>0)?'Scheduled money in and out':'Bills and transfers due' }} by {{ shortDate(breakdown.low_point_date) }}</dt><dd>{{ signedMoney(breakdown.scheduled_cents) }}</dd></div><div v-if="breakdown.set_aside_cents"><dt>Savings already set aside</dt><dd>− {{ money(breakdown.set_aside_cents) }}</dd></div><div v-if="breakdown.allowance_cents"><dt>Everyday spending · {{ breakdown.allowance_days }} {{ breakdown.allowance_days===1?'day':'days' }}</dt><dd>− {{ money(breakdown.allowance_cents) }}</dd></div><div v-if="breakdown.cushion_cents"><dt>Your safety cushion</dt><dd>− {{ money(breakdown.cushion_cents) }}</dd></div><div class="spend-total"><dt>{{ (data.forecast.headroom_cents??0)<0?'Short by':'Safe to spend' }}</dt><dd>= {{ money(Math.abs(data.forecast.headroom_cents??0)) }}</dd></div></dl><button class="text-button" @click="openModal('explain')">How this is calculated <FinanceIcon name="arrow"/></button></section>
     <section class="trajectory-panel"><div class="section-heading"><div><p class="page-kicker">{{ glanceView==='calendar'?'Day by day':'Room to move' }}</p><h2>{{ glanceView==='calendar'?'Your money calendar':'Your cash trajectory' }}</h2></div><div class="glance-actions"><div class="view-toggle" role="group" aria-label="Panel view"><button type="button" :aria-pressed="glanceView==='trajectory'" @click="glanceView='trajectory'"><FinanceIcon name="forecast"/><span>Trajectory</span></button><button type="button" :aria-pressed="glanceView==='calendar'" @click="glanceView='calendar'"><FinanceIcon name="calendar"/><span>Calendar</span></button></div><RouterLink :to="link(glanceView==='calendar'?'calendar':'forecast')" class="text-button">{{ glanceView==='calendar'?'Open calendar':'Explore forecast' }} <FinanceIcon name="arrow"/></RouterLink></div></div><div class="glance-views"><div :class="{'glance-hidden':glanceView!=='trajectory'}" :inert="glanceView!=='trajectory'"><CashTrajectory :forecast="data.forecast" :cushion="data.settings.cushion_cents"/></div><div :class="{'glance-hidden':glanceView!=='calendar'}" :inert="glanceView!=='calendar'"><CalendarGlance :data="data"/></div></div><div class="trajectory-footnote"><template v-if="glanceView==='trajectory'"><span><i class="status-dot"/> {{ data.forecast.daily.some(d=>d.balance_cents<(data?.settings.cushion_cents??0))?'Your forecast dips below your cushion. Review upcoming commitments.':'Your planned cash stays above your cushion.' }}</span><span>90-day outlook</span></template><template v-else><span><i class="status-dot"/> Scheduled entries are plans; recorded activity has already happened.</span><span>Arrow keys move between days</span></template></div></section>
    </div>
    <div v-if="data.forecast.warnings.length" class="forecast-warnings"><p v-for="warning in data.forecast.warnings" :key="warning">{{ warning }}</p><button class="text-button" @click="openModal('commitment')">Add income or commitments <FinanceIcon name="arrow"/></button></div>
    <div class="overview-secondary"><section class="up-next"><div class="section-heading"><h2>Coming up next</h2><RouterLink :to="link('plans')" class="text-button">See all <FinanceIcon name="arrow"/></RouterLink></div><div v-for="c in upcoming.slice(0,4)" :key="c.key" class="upcoming-row"><time :datetime="c.next_date"><span>{{ new Date(c.next_date+'T12:00:00').toLocaleDateString('en-US',{month:'short'}) }}</span><strong>{{ c.next_date.slice(8) }}</strong></time><span class="row-description"><strong>{{ c.name }}</strong><small>{{ c.kind==='income'?'Money coming in':accountName(c.account_id) }}</small></span><span class="row-amount" :class="{positive:c.kind==='income'}">{{ c.kind==='income'?'+':'−' }}{{ money(c.amount_cents) }}</span></div><div v-if="!upcoming.length" class="inline-empty">Nothing scheduled yet. <button class="text-button" @click="openModal('commitment')">Add your next paycheck or bill</button></div></section><section class="goals-preview"><div class="section-heading"><h2>Ahead, by design</h2><RouterLink :to="link('plans')" class="text-button">Your plans <FinanceIcon name="arrow"/></RouterLink></div><div v-for="goal in data.goals.slice(0,2)" :key="goal.id" class="goal-progress"><div><strong>{{ goal.name }}</strong><span>{{ Math.round(goal.saved_cents/(goal.target_cents||1)*100) }}%</span></div><progress :value="goal.saved_cents" :max="goal.target_cents" :aria-label="goal.name"/><p>{{ money(goal.saved_cents,0) }} <span>of {{ money(goal.target_cents,0) }}</span></p></div><div v-if="!data.goals.length" class="inline-empty"><p>Give your savings something to work toward.</p><RouterLink v-if="!isDemo" :to="link('plans')" class="text-button">Start a vault <FinanceIcon name="arrow"/></RouterLink><button v-else class="text-button" @click="resetDemo">Restore sample goals</button></div><div class="debt-mini"><FinanceIcon name="accounts"/><div><small>Credit card balances</small><strong>{{ money(debt) }}</strong></div><RouterLink :to="link('accounts')" class="icon-button" aria-label="View credit card balances"><FinanceIcon name="arrow"/></RouterLink></div></section></div>
    <section class="recent-section"><div class="section-heading"><h2>The latest little things</h2><RouterLink :to="link('activity')" class="text-button">All activity <FinanceIcon name="arrow"/></RouterLink></div><div v-for="m in movements.slice(0,3)" :key="m.id" class="activity-row"><span class="activity-symbol" :class="m.kind"><FinanceIcon :name="m.kind==='transfer'?'arrow':m.kind==='income'?'forecast':'activity'"/></span><span class="row-description"><strong>{{ m.description||'Untitled activity' }}</strong><small>{{ accountName(m.account_id) }} · {{ shortDate(m.date) }}</small></span><span class="row-amount" :class="{positive:m.kind==='income'}">{{ m.kind==='income'?'+':'−' }}{{ money(m.amount_cents) }}</span></div><p v-if="!movements.length" class="inline-empty">Your recent activity will appear here after your first entry.</p></section>
   </template>
   <FinanceCalendar v-else-if="section==='calendar'" :data="data" @activity="openModalOnDate('movement',$event)" @commitment="openModalOnDate('commitment',$event)"/>
   <template v-else-if="section==='activity'">
    <div class="ledger-toolbar"><label class="search-field"><FinanceIcon name="search"/><input v-model="search" type="search" placeholder="Find an entry or account" aria-label="Search activity"/></label><select v-model="kindFilter" aria-label="Filter activity type"><option value="all">All activity</option><option value="expense">Expenses</option><option value="income">Income</option><option value="transfer">Transfers</option></select><label class="btn btn-secondary import-trigger"><FinanceIcon name="download"/> Import CSV<input type="file" accept=".csv,text/csv" @change="readCsv"/></label></div>
    <div class="ledger-labels"><span>Activity</span><span>Amount</span><span>Actions</span></div><div v-for="m in movements" :key="m.id" class="activity-row full-row"><span class="activity-symbol" :class="m.kind"><FinanceIcon :name="m.kind==='transfer'?'arrow':m.kind==='income'?'forecast':'activity'"/></span><span class="row-description"><strong>{{ m.description||'Untitled activity' }}</strong><small>{{ accountName(m.account_id) }}<template v-if="m.transfer_account_id"> → {{ accountName(m.transfer_account_id) }}</template> · {{ shortDate(m.date) }} · {{ m.kind }}</small></span><span class="row-amount" :class="{positive:m.kind==='income'}">{{ m.kind==='income'?'+':m.kind==='transfer'?'':'−' }}{{ money(m.amount_cents) }}</span><div class="row-actions"><button @click="openModal('movement',m)" :aria-label="'Edit '+m.description">Edit</button><button @click="removeMovement(m)" :aria-label="'Delete '+m.description">Delete</button></div></div><div v-if="!movements.length" class="inline-empty spacious"><h2>{{ search?'No matching entries.':'A clean slate.' }}</h2><p>{{ search?'Try a different description or account.':'Add an expense, income, or transfer. Your balances update with every entry.' }}</p><button v-if="!search" class="btn btn-primary" @click="openModal('movement')">Add activity</button></div>
   </template>
   <template v-else-if="section==='accounts'">
    <div class="account-totals"><div><span>Total balance</span><strong>{{ money(worth) }}</strong></div><div><span>Spending cash</span><strong>{{ money(cash) }}</strong></div><div><span>Credit card debt</span><strong>{{ money(debt) }}</strong></div></div><div class="accounts-list"><article v-for="a in data.accounts" :key="a.id" class="finance-account"><div class="account-emblem"><FinanceIcon name="accounts"/></div><div class="account-info"><span>{{ a.type.replace('_',' ') }} <span v-if="a.spendable" class="account-spendable">Spending account</span></span><h2>{{ a.name }}</h2><p>{{ a.type==='credit_card'?'Owed balances appear as negative.':'Manually tracked · reconcile with your statement' }}</p></div><div class="account-balance"><strong>{{ money(a.balance_cents) }}</strong><button class="text-button" @click="openModal('reconcile',a)">Reconcile balance <FinanceIcon name="arrow"/></button></div></article></div><div class="account-note"><FinanceIcon name="check"/><p>Your balances are under your control. Adding activity changes them; reconciliation records the difference from your statement.</p></div><RouterLink v-if="!isDemo" to="/accounts" class="text-button">Manage legacy bank accounts <FinanceIcon name="arrow"/></RouterLink>
   </template>
   <template v-else-if="section==='forecast'">
    <div class="forecast-layout"><section class="trajectory-panel forecast-chart"><div class="section-heading"><div><p class="page-kicker">From {{ shortDate(data.forecast.from) }} to {{ shortDate(data.forecast.to) }}</p><h2>The shape of your cash</h2></div><span class="pill">{{ scenario?'What-if active':'Your baseline' }}</span></div><CashTrajectory :forecast="data.forecast" :scenario="scenario" :cushion="data.settings.cushion_cents"/><div class="forecast-summary"><div><small>Lowest projected balance</small><strong>{{ money(Math.min(...(scenario??data.forecast).daily.map(d=>d.balance_cents)),0) }}</strong></div><div><small>Balance in 90 days</small><strong>{{ money((scenario??data.forecast).daily.at(-1)?.balance_cents,0) }}</strong></div></div></section><form class="what-if-panel" @submit.prevent="runWhatIf"><span class="what-if-mark">↗</span><h2>What if…</h2><p>Try a change. See how much room it leaves.</p><label class="field">I have an extra<select v-model="whatDirection"><option value="expense">Expense</option><option value="income">Income</option></select></label><label class="field">Amount ($)<input type="number" min="0.01" step="0.01" v-model="whatAmount" required/></label><label class="field">On this date<input type="date" :min="data.forecast.from" :max="data.forecast.to" v-model="whatDate" required/></label><button class="btn btn-primary" :disabled="busy">{{ busy?'Calculating…':'See the impact' }}<FinanceIcon name="arrow"/></button><button v-if="scenario" type="button" class="text-button" @click="scenario=null">Clear scenario</button><small>Temporary only. Your accounts and commitments stay as they are.</small></form></div><section class="forecast-schedule"><div class="section-heading"><h2>What’s shaping the line</h2><RouterLink :to="link('plans')" class="text-button">Edit commitments <FinanceIcon name="arrow"/></RouterLink></div><div v-for="c in upcoming" :key="c.key" class="scheduled-row"><span class="schedule-date">{{ shortDate(c.next_date) }}</span><strong>{{ c.name }}</strong><span class="pill">{{ c.frequency }}</span><span class="row-amount" :class="{positive:c.kind==='income'}">{{ c.kind==='income'?'+':'−' }}{{ money(c.amount_cents) }}</span></div><p v-if="!upcoming.length" class="inline-empty">Add your income and bills to make this forecast useful.</p></section><p v-for="warning in data.forecast.warnings" :key="warning" class="forecast-warnings">{{ warning }}</p>
   </template>
   <template v-else-if="section==='plans'">
    <div class="plans-intro"><div><h2>A destination for every dollar.</h2><p>Protect your everyday needs, plan your payments, and keep your goals moving.</p></div><button class="btn btn-secondary" @click="openModal('settings')">Set your guardrails</button></div><FinanceVaults :data="data" :demo="isDemo" @save-goal="saveDemoGoal" @delete-goal="deleteDemoGoal" @saved="vaultSaved"/><section><div class="section-heading"><h2>Your commitments</h2><span class="subtle">{{ data.commitments.length }} scheduled</span></div><div v-for="c in data.commitments" :key="c.key" class="commitment-row"><span class="activity-symbol" :class="{income:c.kind==='income'}"><FinanceIcon :name="c.kind==='income'?'forecast':c.kind==='savings'?'plans':'activity'"/></span><div class="row-description"><strong>{{ c.name }}</strong><small>{{ c.kind }} · {{ c.frequency }} · next {{ shortDate(c.next_date) }}</small></div><strong class="row-amount" :class="{positive:c.kind==='income'}">{{ c.kind==='income'?'+':'−' }}{{ money(c.amount_cents) }}</strong><div class="row-actions"><button @click="openModal('commitment',c)">Edit</button><button @click="removeCommitment(c)">Stop</button></div></div></section><div v-if="!isDemo" class="legacy-planning"><RouterLink to="/debts"><strong>Find your debt-free date</strong><span>Compare avalanche & snowball strategies <FinanceIcon name="arrow"/></span></RouterLink><RouterLink to="/paycheck"><strong>Give your paycheck a plan</strong><span>Manage income & account splits <FinanceIcon name="arrow"/></span></RouterLink><RouterLink to="/bills"><strong>Keep your bills in order</strong><span>Manage monthly bills <FinanceIcon name="arrow"/></span></RouterLink><RouterLink to="/investments"><strong>Invest in your future</strong><span>Manage investment contributions <FinanceIcon name="arrow"/></span></RouterLink></div>
   </template>
  </template>
  <footer class="finance-footer"><span>Budget Tool <span class="footer-dot">·</span> A clearer relationship with money.</span><span>{{ isDemo?'Sample workspace':'Manually tracked' }} <span class="footer-dot">·</span> {{ data?shortDate(data.as_of):'' }}</span></footer>
 </div>
 <dialog ref="dialog" class="finance-dialog" @close="closeModal" @click="($event.target===dialog)&&closeModal()">
  <div class="dialog-content"><div class="section-heading"><h2>{{ modal==='movement'?(editing?'Edit activity':'Add activity'):modal==='account'?'Add an account':modal==='reconcile'?'Reconcile balance':modal==='commitment'?(editing?'Edit commitment':'Plan a commitment'):modal==='settings'?'Protect your breathing room':modal==='explain'?'How safe to spend works':'Import activity' }}</h2><button class="icon-button" aria-label="Close dialog" @click="closeModal"><FinanceIcon name="close"/></button></div><p v-if="error" role="alert" class="alert">{{ error }}</p>
   <div v-if="modal==='explain'" class="spend-explainer"><p class="spend-explainer-lede">Safe to spend answers one question: <strong>how much can you spend right now without coming up short before {{ paydayLabel }}?</strong></p>
    <ol><li><strong>Start with your spending cash.</strong> Today’s balance in the accounts you use for everyday spending ({{ spendingAccountNames }}).</li><li><strong>Walk forward to payday, one day at a time.</strong> Each scheduled bill, card payment or transfer comes out on its due date. Your next paycheck only counts once it lands, so it can’t pay for bills due before it.</li><li><strong>Hold back what’s already spoken for.</strong> Savings goals kept in those accounts, your safety cushion, and an everyday allowance for groceries, gas and the like that grows a little each day.</li><li><strong>Use the tightest day.</strong> Whatever is left on the day your cash runs lowest<template v-if="breakdown"> ({{ shortDate(breakdown.low_point_date) }})</template> is your safe to spend. Spend more than that today and you’d come up short that day.</li></ol>
    <section v-if="breakdown?.scheduled_items.length" class="spend-explainer-items" aria-labelledby="spend-items-title"><h3 id="spend-items-title">Scheduled by {{ shortDate(breakdown.low_point_date) }}</h3><div v-for="item in breakdown.scheduled_items" :key="item.date+item.name+item.amount_cents" class="spend-item"><time>{{ shortDate(item.date) }}</time><span>{{ item.name }}</span><b :class="{positive:item.amount_cents>0}">{{ signedMoney(item.amount_cents) }}</b></div></section>
    <p v-else-if="breakdown" class="subtle">Nothing is scheduled to come out before then.</p>
    <p class="subtle">Recorded purchases lower your cash right away, so this number updates as you spend.</p>
    <div class="dialog-actions"><button type="button" class="btn btn-secondary" @click="modal='settings'">Adjust cushion &amp; allowance</button><button type="button" class="btn btn-primary" @click="closeModal">Got it</button></div></div>
   <form v-if="['movement','account','reconcile','commitment'].includes(modal)" @submit.prevent="save" class="finance-form">
    <label v-if="modal==='account'||modal==='commitment'" class="field">Name<input v-model="form.name" required maxlength="120" autofocus/></label>
    <template v-if="modal==='movement'||modal==='commitment'"><label class="field">{{ modal==='movement'?'Activity type':'Commitment type' }}<select v-model="form.kind" required><option value="income">Income</option><option value="expense">Expense</option><option v-if="modal==='movement'" value="transfer">Transfer between accounts</option><template v-else><option value="bill">Bill</option><option value="debt">Debt payment</option><option value="savings">Savings</option><option value="investment">Investment</option></template></select></label><label v-if="modal==='movement'" class="field">Description<input v-model="form.description" required maxlength="200" placeholder="What was it for?"/></label><label class="field">Amount ($)<input v-model="form.amount" type="number" min="0.01" step="0.01" required/></label><label class="field">{{ form.kind==='income'?'Receiving account':'From account' }}<select v-model="form.account_id" required><option v-for="a in data?.accounts" :key="a.id" :value="a.id">{{ a.name }}</option></select></label><label v-if="form.kind==='transfer'||(modal==='commitment'&&['savings','debt','investment'].includes(form.kind))" class="field">To account<select v-model="form.transfer_account_id" :required="form.kind==='transfer'"><option :value="0" v-if="form.kind!=='transfer'">External / no destination</option><option v-for="a in data?.accounts.filter(a=>a.id!==Number(form.account_id))" :key="a.id" :value="a.id">{{ a.name }}</option></select></label></template>
    <template v-if="modal==='account'"><label class="field">Account type<select v-model="form.type"><option value="checking">Checking</option><option value="savings">Savings</option><option value="cash">Cash</option><option value="credit_card">Credit card</option><option value="investment">Investment</option><option value="other">Other</option></select></label><label class="checkbox-field"><input type="checkbox" v-model="form.spendable"/> Include in spending cash</label><p class="subtle">Exclude savings and credit cards from spending cash.</p></template>
    <label v-if="modal==='account'||modal==='reconcile'" class="field">{{ modal==='reconcile'?'Statement balance ($)':'Starting balance ($)' }}<input type="number" step="0.01" v-model="form.balance" required/><small v-if="form.type==='credit_card'">Enter an owed balance as a negative number.</small></label>
    <label class="field">{{ modal==='commitment'?'Next date':'Date' }}<input type="date" v-model="form.date" required/></label>
    <label v-if="modal==='commitment'" class="field">Repeats<select v-model="form.frequency"><option value="once">Once</option><option value="weekly">Weekly</option><option value="biweekly">Every two weeks</option><option value="semimonthly">Twice a month</option><option value="monthly">Monthly</option></select></label><p v-if="modal==='reconcile'" class="subtle">We’ll record the difference as an adjustment so your history stays intact.</p><div class="dialog-actions"><button type="button" class="btn btn-secondary" @click="closeModal">Cancel</button><button class="btn btn-primary" :disabled="busy">{{ busy?'Saving…':modal==='reconcile'?'Reconcile balance':'Save changes' }}</button></div>
   </form>
   <form v-else-if="modal==='settings'" class="finance-form" @submit.prevent="saveSettings"><p>Safe to spend uses the lowest projected cash headroom through your next deposit, or a labeled 30-day fallback. Scheduled commitments are already included.</p><fieldset class="spending-accounts-field"><legend>Spending accounts</legend><p>Choose the checking and cash accounts used for your everyday spending.</p><label v-for="account in data?.accounts.filter(a=>a.spendable&&['checking','cash'].includes(a.type))" :key="account.id" class="checkbox-field"><input v-model="selectedSpendingAccounts" type="checkbox" :value="account.id"/> {{ account.name }}</label><small v-if="!data?.accounts.some(a=>a.spendable&&['checking','cash'].includes(a.type))">Add a checking or cash account first.</small></fieldset><label class="field">Protected cushion ($)<input type="number" min="0" step="0.01" v-model="cushion" required/><small>Money you always want to leave untouched.</small></label><label class="field">Everyday allowance ($)<input type="number" min="0" step="0.01" v-model="allowance" required/><small>Room for groceries, transport, and other unscheduled essentials until your next income.</small></label><button class="btn btn-primary" :disabled="busy">Save guardrails</button></form>
   <div v-else-if="modal==='import'" class="finance-form"><p>{{ csvRows.length }} rows ready to map. Use YYYY-MM-DD dates. Negative amounts are expenses; positive amounts are income.</p><div class="form-row"><label class="field">Date column<select v-model="mapDate"><option value="" disabled>Choose column</option><option v-for="h in csvHeaders" :key="h">{{ h }}</option></select></label><label class="field">Amount column<select v-model="mapAmount"><option value="" disabled>Choose column</option><option v-for="h in csvHeaders" :key="h">{{ h }}</option></select></label></div><label class="field">Description column<select v-model="mapDescription"><option value="">No description</option><option v-for="h in csvHeaders" :key="h">{{ h }}</option></select></label><label class="field">Import into<select v-model="importAccount"><option v-for="a in data?.accounts" :value="a.id" :key="a.id">{{ a.name }}</option></select></label><div class="import-preview"><div v-for="(r,i) in importRows.slice(0,5)" :key="i"><span>{{ r.date }}</span><span>{{ r.description }}</span><strong>{{ money(r.amount_cents) }}</strong></div></div><div v-if="preview" class="import-result" role="status"><p>{{ preview.can_import?'Preview passed. Ready to import.':'Fix the rows below before importing.' }}</p><p v-for="row in preview.rows.filter(r=>!r.valid||r.duplicate)" :key="row.row">Row {{ row.row }}: {{ row.duplicate?'Duplicate — will be skipped':row.errors.join(', ') }}</p></div><div class="dialog-actions"><button class="btn btn-secondary" @click="closeModal">Cancel</button><button v-if="!preview?.can_import" class="btn btn-primary" :disabled="busy||!mapDate||!mapAmount" @click="previewImport">Preview import</button><button v-else class="btn btn-primary" :disabled="busy" @click="importCsv">Import {{ csvRows.length }} entries</button></div></div>
  </div>
 </dialog>
</template>
